function buildCard(title: string, rows: Array<[string, string | number]>): string {
  const body = rows
    .map(
      ([key, value]) =>
        `<div class="row"><span class="label">${escapeHtml(key)}</span><span class="value">${escapeHtml(String(value))}</span></div>`,
    )
    .join('');

