function mapObjectKindToEntryKind(
  objectKind: PantavionAdmissionObjectKind,
): PantavionCapabilityEntryKind {
  switch (objectKind) {
    case 'module':
      return 'module';
    case 'runtime':
      return 'runtime';
    case 'workspace':
      return 'workspace';
    case 'protocol-adapter':
      return 'adapter';
    case 'service':
      return 'service';
    case 'governed-surface':
      return 'governed-surface';
    case 'registry-family':
      return 'surface';
    default:
      return 'capability';
  }
}

